Script.script:
-- Mudlet base UI: a small starter interface that adapts to whatever the game -- provides. Nothing is created until the game actually sends something: -- vitals gauges are built from GMCP character data (normalised across the -- dialects games speak, and only for the fields that exist), with the map and -- chat windows alongside them. Chat comes from gmcp.Comm.Channel.Text when -- the game offers it; for everything else, additive triggers capture the -- common chat-line shapes (tells, says, channels) shared by most games - so -- on a game with no GMCP at all the UI appears on the first chat line. -- Chat is sorted into All/Tells/Channels tabs, and the map pane shows a -- placeholder until the profile actually has map data. -- Gauges have their own fallback ladder when GMCP is missing: MSDP is -- negotiated quietly, self-sufficient prompt lines (labelled cur/max or -- percent) are trusted once they recur, score screens are read passively, -- and as a last resort "score" is sent once - visibly - to learn the maxima -- on games whose prompt only carries current values. -- Type "baseui" for options; "baseui hide" removes it until "baseui show".
BaseUI = BaseUI or {} BaseUI.gauges = BaseUI.gauges or {} BaseUI.usedGaugeSlots = BaseUI.usedGaugeSlots or 0 BaseUI.chatTriggerIds = BaseUI.chatTriggerIds or {} BaseUI.recentCaptures = BaseUI.recentCaptures or {} BaseUI.vitalsTriggerIds = BaseUI.vitalsTriggerIds or {} BaseUI.shapeSightings = BaseUI.shapeSightings or {} BaseUI.vitalsData = BaseUI.vitalsData or {} BaseUI.vitalsLock = BaseUI.vitalsLock or 0
local settingsFile = getMudletHomeDir() .. "/base_ui_settings.lua"
-- one dark theme for the whole dock; the accent appears only on section -- headers and the active chat tab so it stays an accent local theme = { accent = "#4fc1e9", bg = "#1b1e23", panel = "#14171c", border = "#3a4149", borderSoft = "#2b3138", text = "#e8eef4", textDim = "#96a0ab", font = "Ubuntu", }
local layout = { mapHeader = { y = "0%", height = "3%" }, map = { y = "3.5%", height = "33.5%" }, chatHeader = { y = "38.5%", height = "3%" }, tabs = { y = "42.5%", height = "3.8%" }, chat = { y = "46.3%", height = "29.7%" }, gaugeSlots = { "78%", "83.5%", "89%", "94.5%" }, gaugeHeight = "4.5%", }
local headerCss = string.format( [[background-color: transparent; border: 0px; border-bottom: 1px solid %s; padding-left: 2px;]], theme.borderSoft)
local placeholderCss = string.format( [[background-color: %s; border: 1px solid %s; border-radius: 6px;]], theme.panel, theme.borderSoft)
local tabCss = { active = string.format( [[background-color: #2b323b; border: 1px solid %s; border-bottom: 2px solid %s; border-top-left-radius: 4px; border-top-right-radius: 4px;]], theme.border, theme.accent), inactive = string.format( [[background-color: #1f242a; border: 1px solid %s; border-bottom: 2px solid %s; border-top-left-radius: 4px; border-top-right-radius: 4px;]], theme.borderSoft, theme.borderSoft), }
-- every gauge shares one look, a thin HUD line: bold value text floating -- over a transparent zone, with a slim stat-colored line along the bottom -- 30% tracking the value. The band edge is a hard gradient stop - Qt -- gradient stops don't alpha-composite, so each band is either fully -- transparent or fully opaque local function gaugeStyle(color) return string.format( [[background-color: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 rgba(0,0,0,0), stop:0.6999 rgba(0,0,0,0), stop:0.70 %s, stop:1 %s); border: none;]], color, color) end
local gaugeBack = gaugeStyle("#2c313a")
-- the text label spans the whole gauge; the padding floats the value text -- above the line, inset from the left edge local gaugeText = [[background-color: transparent; padding-left: 8px; padding-bottom: 9px;]]
local gaugeDefs = { hp = { front = gaugeStyle("#2f9e3f") }, mp = { front = gaugeStyle("#2f6f9e") }, xp = { front = gaugeStyle("#c28f2c") }, mv = { front = gaugeStyle("#2f9e8a") }, enemy = { front = gaugeStyle("#b23a3a") }, }
-- GMCP vitals arrive in several dialects: lowercase namespaces, maxima inside -- the vitals message or in a separate Maxstats one, and varying key names. -- Every node listed here is scanned on each update (the gmcp table keeps the -- latest message per node, so currents and maxima merge naturally even when -- they arrive separately) - supporting another dialect is one more line local vitalsNodes = { { "Char", "Vitals" }, { "char", "vitals" }, { "Char", "Maxstats" }, { "char", "maxstats" }, { "Char", "Status" }, { "char", "status" }, }
-- one row per gauge; current/max/percent list every key spelling observed in -- the wild. A percent key is a ready 0-100 value and needs no max: nl (IRE -- next-level percent) and tnlpct for xp, opponent_hp_pct and enemypct for -- enemy health. transient rows hide their gauge when the value goes away -- (the enemy died or was cleared). local vitalsStats = { { key = "hp", label = "HP", current = { "hp", "health" }, max = { "maxhp", "max_hp", "maxHp", "maxhealth", "max_health", "maxHealth" } }, { key = "mp", label = "MP", current = { "mp", "mana", "sp", "energy" }, max = { "maxmp", "max_mp", "maxMp", "maxmana", "max_mana", "maxMana", "maxsp", "max_sp", "maxSp", "maxenergy", "max_energy", "maxEnergy" } }, { key = "xp", label = "XP", percent = { "nl", "tnlpct" }, current = { "xp", "experience" }, max = { "maxxp", "max_xp", "maxXp", "maxexperience", "max_experience", "maxExperience" } }, { key = "enemy", label = "Enemy", transient = true, percent = { "opponent_hp_pct", "enemypct" } }, -- last on purpose: when a game supplies more stats than there are gauge -- slots, movement is the one to lose out { key = "mv", label = "MV", current = { "mv", "moves", "movement" }, max = { "maxmv", "max_mv", "maxMv", "maxmoves", "max_moves", "maxMoves", "maxmovement", "max_movement", "maxMovement" } }, }
-- vitals can also come from MSDP or from prompt/score lines. A source lock -- keeps them from fighting: the first source to produce a complete hp -- reading owns the gauges, and only a higher-ranked source can take them -- over - so gauges built from a prompt hand themselves to GMCP whenever it -- turns up, however late local sourceRanks = { gmcp = 3, msdp = 2, prompt = 1 }
-- the vitalsStats rows again, keyed by the conventional MSDP variable names local msdpStats = { { key = "hp", current = "HEALTH", max = "HEALTH_MAX" }, { key = "mp", current = "MANA", max = "MANA_MAX" }, { key = "xp", current = "EXPERIENCE", max = "EXPERIENCE_MAX" }, { key = "mv", current = "MOVEMENT", max = "MOVEMENT_MAX" }, { key = "enemy", current = "OPPONENT_HEALTH", max = "OPPONENT_HEALTH_MAX", transient = true }, }
local function gmcpNode(path) local node = gmcp for _, key in ipairs(path) do if type(node) ~= "table" then return nil end node = node[key] end if type(node) == "table" then return node end end
-- some games send numbers as strings, hence the tonumber()s; nested -- cur/max tables (vitals.hp = { cur = 10, max = 20 }) are handled too local function statReading(sources, stat) local current, max, percent for _, source in ipairs(sources) do for _, name in ipairs(stat.percent or {}) do percent = percent or tonumber(source[name]) end for _, name in ipairs(stat.current or {}) do local value = source[name] if type(value) == "table" then current = current or tonumber(value.cur) max = max or tonumber(value.max) else current = current or tonumber(value) end end for _, name in ipairs(stat.max or {}) do max = max or tonumber(source[name]) end end return current, max, percent end
-- generic chat capture for games without GMCP chat: trigger shapes most games -- share. Capture is additive - the matched line is copied into the chat window -- with its colours and never removed from the main one. -- a "[tag]", "(tag)" or "< tag |" prefix only counts as chat when its first -- word is a well-known channel name - extend this list to cover more games BaseUI.chatChannelNames = { chat = true, say = true, tell = true, tells = true, gtell = true, newbie = true, newbies = true, gossip = true, grats = true, gratz = true, congrats = true, ooc = true, ic = true, clan = true, guild = true, order = true, house = true, city = true, market = true, auction = true, trade = true, talk = true, ask = true, answer = true, question = true, questions = true, music = true, quote = true, roleplay = true, rp = true, imm = true, group = true, party = true, team = true, shout = true, yell = true, form = true, town = true, }
-- entries with tagged = true capture a channel tag that must pass the list -- above; family routes a line into the Tells or Channels tab as well as All local chatPatterns = { { regex = [=[^\w[\w'-]* tells you\b[^,:]{0,30}(?::|,?\s*['"])]=], family = "tells" }, { regex = [=[^You tell [\w'-]+[^,:]{0,30}(?::|,?\s*['"])]=], family = "tells" }, { regex = [=[^You tell the (?:group|formation)\b]=], family = "tells" }, { regex = [=[^\w[\w'-]* whispers to you\b[^,:]{0,30}(?::|,?\s*['"])]=], family = "tells" }, { regex = [=[^\w[\w'-]* tells the (?:group|formation)\b]=], family = "tells" }, { regex = [=[^\w[\w'-]* (?:says|asks|exclaims)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^You (?:say|ask|exclaim)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^\w[\w'-]* (?:yells|shouts)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^You (?:yell|shout)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^\[([\w][\w -]{0,18})\]]=], tagged = true }, { regex = [=[^\(([\w -]{1,18})\)[:\s]]=], tagged = true }, { regex = [=[^< ?([\w -]{1,18}) ?\|]=], tagged = true }, }
local chatTabs = { { key = "all", label = "All" }, { key = "tells", label = "Tells" }, { key = "channels", label = "Channels" }, }
function BaseUI.routeChatLine(family) -- gmcpChat means the trigger layer is retired: killing a trigger does not -- stop it firing on lines from the batch already being processed -- several patterns can match the same line - copy it only once if BaseUI.gmcpChat or BaseUI.dormant() or getLineNumber() == BaseUI.lastChatLine then return end BaseUI.lastChatLine = getLineNumber() selectCurrentLine() copy() deselect() local firstBuild = not BaseUI.container BaseUI.build() if firstBuild then -- building resizes the main window, which can renumber lines; refresh the -- marker so other patterns matching this same line stay deduplicated BaseUI.lastChatLine = getLineNumber() end if not BaseUI.chats then return end BaseUI.chats.all:appendBuffer() BaseUI.noteChatActivity("all") if family and BaseUI.chats[family] then BaseUI.chats[family]:appendBuffer() BaseUI.noteChatActivity(family) end BaseUI.checkMapData() table.insert(BaseUI.recentCaptures, { text = line, time = getEpoch() }) if #BaseUI.recentCaptures > 10 then table.remove(BaseUI.recentCaptures, 1) end end
function BaseUI.routeTaggedChatLine() local tag = matches[2]:match("(%S+)") if not tag then return end tag = tag:lower() if not BaseUI.chatChannelNames[tag] then return end local family = (tag == "tell" or tag == "tells" or tag == "gtell") and "tells" or "channels" BaseUI.routeChatLine(family) end
function BaseUI.createChatTriggers() if BaseUI.dormant() or BaseUI.gmcpChat or next(BaseUI.chatTriggerIds) then return end for _, pattern in ipairs(chatPatterns) do local handler if pattern.tagged then handler = BaseUI.routeTaggedChatLine else local family = pattern.family handler = function() BaseUI.routeChatLine(family) end end table.insert(BaseUI.chatTriggerIds, tempRegexTrigger(pattern.regex, handler)) end end
function BaseUI.killChatTriggers() for _, id in ipairs(BaseUI.chatTriggerIds) do killTrigger(id) end BaseUI.chatTriggerIds = {} end
-- vitals from plain text, for games that offer no protocol at all. Only -- self-sufficient shapes may drive a gauge: a labelled cur/max pair, a -- labelled percentage, or a labelled score-screen line - current-only -- prompts never invent a maximum. kind = "bare" rows exist to recognise -- those current-only prompts: they update currents once a maximum is known -- and arm the one-time auto-"score" request, nothing more. gated rows only -- go live after matching on three separate lines (prompts recur; chat -- mentions do not); score-screen rows are trusted on first sight because a -- score may only ever be shown once. -- two disambiguation lookbehinds recur below. On label-after shapes, -- (?<![\d:=])(?<![:=][ ]) keeps the numbers of a label-first reading from -- being claimed by the NEXT label ("HP: 523/600 MP: ..." must not read as -- 523/600 mp). On label-first shapes, (?<![\d%])(?<!\d[ ]) keeps a label -- that closes a label-after reading from opening a new one ("87%hp 80%m" -- must not read as hp 80). local vitalsLinePatterns = { -- self-sufficient prompt shapes: cur/max with the label after the numbers { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)\s*/\s*(\d+)\s*(?:hp|health|hits?)\b]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)\s*/\s*(\d+)\s*(?:mp|mana|sp|magic|energy|m)\b]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)\s*/\s*(\d+)\s*(?:mv|moves?|movement|end(?:urance)?|st(?:amina)?)\b]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)\s*/\s*(\d+)\s*(?:xp|exp|tnl)\b]=] }, -- self-sufficient prompt shapes: cur/max with the label first. The -- explicit-separator form is trusted anywhere; the separator-less form -- needs the digit lookbehinds so "523/600 hp ..." cannot have its own -- trailing label re-read as the start of a new reading { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:hp|health|hits?)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:hp|health|hits?)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:mp|mana|sp|magic|energy)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:mp|mana|sp|magic|energy)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:mv|moves?|movement|end(?:urance)?|st(?:amina)?)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:mv|moves?|movement|end(?:urance)?|st(?:amina)?)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:xp|exp|tnl)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:xp|exp|tnl)\s*(\d+)\s*/\s*(\d+)]=] }, -- labelled percentages need no maximum at all { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)%\s*(?:hp|health)\b]=] }, { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)(?<!%)\b(?:hp|health)[:=]\s*(\d+)%]=] }, { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:hp|health)\s*(\d+)%]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)(?<![\d:=])(?<![:=][ ])(\d+)%\s*(?:mp|mana|sp|m)\b]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)(?<!%)\b(?:mp|mana|sp)[:=]\s*(\d+)%]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)(?<![\d%])(?<!\d[ ])\b(?:mp|mana|sp)\s*(\d+)%]=] }, -- score-screen lines: a label anchored at the start of a formatted line { stat = "hp", kind = "curmax", regex = [=[(?i)^\s*(?:health|hit\s*points?|hp)\s*[:\]]*\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mp", kind = "curmax", regex = [=[(?i)^\s*(?:mana|magic|spell\s*points?|sp|mp)\s*[:\]]*\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mv", kind = "curmax", regex = [=[(?i)^\s*(?:move(?:ment)?s?|vitality|stamina|mv)\s*[:\]]*\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "hp", kind = "curmax", regex = [=[(?i)(\d+)\s*/\s*(\d+)\s*hit points\b]=] }, -- current-only prompt shapes; the lookarounds keep them off cur/max and -- percentage lines, which belong to the shapes above { stat = "hp", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*h(?:p|its?)?\b(?!\s*[/%])]=] }, { stat = "hp", kind = "bare", gated = true, regex = [=[(?i)\b(?:hp|health|hits?)[:=]\s*(\d+)\b(?!\s*[/%.])]=] }, { stat = "mp", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*m(?:p|ana)?\b(?!\s*[/%])]=] }, { stat = "mp", kind = "bare", gated = true, regex = [=[(?i)\b(?:mp|mana|sp)[:=]\s*(\d+)\b(?!\s*[/%.])]=] }, { stat = "mv", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*(?:mv|moves?)\b(?!\s*[/%])]=] }, }
-- lines the chat layer would route are never harvested for vitals - a tell -- saying "I am on 100/120 hp" is conversation, not a prompt function BaseUI.chatLikeLine(text) for _, pattern in ipairs(chatPatterns) do local capture = rex.match(text, pattern.regex) if capture then if not pattern.tagged then return true end local tag = type(capture) == "string" and capture:match("(%S+)") if tag and BaseUI.chatChannelNames[tag:lower()] then return true end end end return false end
-- pure so the test suite can drive it: turns one plain-text line into a list -- of { stat, kind, current, max, percent, pattern } readings (kind "bare" -- means a current with no maximum). Chat-shaped lines yield nothing. function BaseUI.parseVitalsLine(text) local readings = {} if type(text) ~= "string" or BaseUI.chatLikeLine(text) then return readings end for index, pattern in ipairs(vitalsLinePatterns) do local first, second = rex.match(text, pattern.regex) local reading if pattern.kind == "curmax" and first then local current, max = tonumber(first), tonumber(second) -- overhealing exists, so a current above the max is fine; a max of -- zero is not if current and max and max > 0 then reading = { stat = pattern.stat, kind = pattern.kind, current = current, max = max } end elseif pattern.kind == "percent" and first then local percent = tonumber(first) if percent and percent <= 100 then reading = { stat = pattern.stat, kind = pattern.kind, percent = percent } end elseif pattern.kind == "bare" and first then reading = { stat = pattern.stat, kind = pattern.kind, current = tonumber(first) } end if reading then reading.pattern = index table.insert(readings, reading) end end return readings end
-- one handler for every vitals pattern: the first trigger to fire on a line -- processes all shapes on it in one pass, later ones see the marker and stop function BaseUI.onVitalsLine() local lineNumber = getLineNumber() if lineNumber == BaseUI.lastVitalsLine or lineNumber == BaseUI.lastChatLine then return end BaseUI.lastVitalsLine = lineNumber local updates = {} for _, reading in ipairs(BaseUI.parseVitalsLine(line)) do local pattern = vitalsLinePatterns[reading.pattern] local live = true if pattern.gated then local seen = (BaseUI.shapeSightings[reading.pattern] or 0) + 1 BaseUI.shapeSightings[reading.pattern] = seen live = seen >= 3 end if live then if pattern.kind == "bare" then BaseUI.maybeRequestScore() end local update = updates[reading.stat] or {} update.current = reading.current or update.current update.max = reading.max or update.max update.percent = reading.percent or update.percent updates[reading.stat] = update end end if next(updates) then BaseUI.applyVitals("prompt", updates) -- building the dock resizes the main window, which can renumber lines; -- refresh the marker so other patterns on this same line stay deduplicated BaseUI.lastVitalsLine = getLineNumber() end end
function BaseUI.createVitalsTriggers() if BaseUI.dormant() or next(BaseUI.vitalsTriggerIds) then return end for _, pattern in ipairs(vitalsLinePatterns) do table.insert(BaseUI.vitalsTriggerIds, tempRegexTrigger(pattern.regex, BaseUI.onVitalsLine)) end end
function BaseUI.killVitalsTriggers() for _, id in ipairs(BaseUI.vitalsTriggerIds) do killTrigger(id) end BaseUI.vitalsTriggerIds = {} end
-- last rung of the ladder: a game whose prompt only carries currents gets -- asked for its score screen - once per session, visibly, and only when no -- protocol has offered vitals and no maximum is known yet. The score output -- is picked up by the always-on score-screen shapes; if it teaches us -- nothing, that is the end of it - no retry, no error. function BaseUI.maybeRequestScore() if BaseUI.scoreRequested or BaseUI.sawGmcpVitals or BaseUI.sawMsdpVitals then return end local hp = BaseUI.vitalsData.hp if hp and (hp.max or hp.percent) then return end local _, _, connected = getConnectionInfo() if not connected then return end BaseUI.scoreRequested = true send("score") cecho("\n<cyan>[ Mudlet UI ] Sent \"score\" once to size your gauges - type <yellow>baseui<cyan> to adjust.<reset>\n") end
function BaseUI.loadSettings() BaseUI.settings = {} if io.exists(settingsFile) and not pcall(table.load, settingsFile, BaseUI.settings) then -- corrupted settings file - start over with the defaults, but say so BaseUI.settings = {} cecho("\n<dim_grey>[ Mudlet UI ] Could not read the saved settings - using the defaults.<reset>\n") end end
function BaseUI.saveSettings() table.save(settingsFile, BaseUI.settings) end
-- the UI keeps out of the way either when the user hid it or when the game -- installed an interface of its own ("standing aside") function BaseUI.dormant() return BaseUI.settings.hidden or BaseUI.settings.standingAside ~= nil end
-- a game that supplies its own interface wins: the moment Mudlet installs a -- Client.GUI package the starter UI stands aside - capture triggers retired, -- dock hidden - and stays aside in later sessions. "baseui show" is the -- deliberate way back for players who prefer this UI regardless. function BaseUI.standAside(_, packageName) local alreadyAside = BaseUI.settings.standingAside ~= nil BaseUI.settings.standingAside = packageName or "the game's interface" BaseUI.saveSettings() BaseUI.killChatTriggers() BaseUI.killVitalsTriggers() if BaseUI.container then BaseUI.container:hide() BaseUI.container:adjustBorder() end -- only players who actually saw this UI need to hear that it is leaving if not alreadyAside and not BaseUI.settings.hidden and (BaseUI.container or BaseUI.settings.announced) then cecho("\n<cyan>[ Mudlet UI ] This game brings its own interface, so the starter UI is stepping aside - type <yellow>baseui show<cyan> if you would rather keep it.<reset>\n") end end
-- if the game's interface is later uninstalled, quietly return to duty. Not -- straight away though: a version upgrade uninstalls only to reinstall a -- moment later, so look again once the dust has settled function BaseUI.serverGuiRemoved(_, packageName) if not BaseUI.settings.standingAside or packageName ~= BaseUI.settings.standingAside then return end tempTimer(10, function() local aside = BaseUI.settings.standingAside if not aside or table.contains(getPackages(), aside) then return end BaseUI.settings.standingAside = nil BaseUI.saveSettings() BaseUI.createChatTriggers() BaseUI.createVitalsTriggers() BaseUI.renderVitals() end) end
function BaseUI.sectionHeader(name, text, spot) local label = Geyser.Label:new({ name = name, x = "0%", y = spot.y, width = "100%", height = spot.height, font = theme.font, fontSize = 9, fgColor = theme.accent, format = "lb", }, BaseUI.container) label:setStyleSheet(headerCss) label:echo(text:upper()) return label end
function BaseUI.mapHasData() return next(getRooms()) ~= nil end
function BaseUI.createMapper() BaseUI.map = Geyser.Mapper:new({ name = "BaseUI_map", x = "0%", y = layout.map.y, width = "100%", height = layout.map.height, }, BaseUI.container) end
-- the embedded mapper shows a clipped "load or create a map" widget while the -- profile has no map data, so a placeholder holds its spot until the first -- room exists (made by a mapping script, a map download or a manual load). -- Cheap to poll: getRooms() stays empty right up until the swap happens. function BaseUI.checkMapData() if not BaseUI.container or BaseUI.map or BaseUI.dormant() then return end if not BaseUI.mapHasData() then return end if BaseUI.mapPlaceholder then BaseUI.mapPlaceholder:hide() end BaseUI.createMapper() end
function BaseUI.build() if BaseUI.container then return end BaseUI.container = Adjustable.Container:new({ name = "BaseUI", x = "75%", y = "0%", width = "25%", height = "100%", attached = "right", titleText = "Mudlet UI", titleTxtColor = theme.text, adjLabelstyle = string.format("background-color: %s; border: 1px solid %s;", theme.bg, theme.border), buttonstyle = string.format( [[QLabel{ border-color: %s; background-color: %s; } QLabel::hover{ background-color: rgba(90,100,110,50%%); }]], theme.border, theme.bg), -- the container's own session persistence can restore a hidden, detached -- state that is impossible to bring back reliably - we persist the only -- choice that matters (hidden or not) ourselves autoLoad = false, autoSave = false, }) BaseUI.mapHeader = BaseUI.sectionHeader("BaseUI_map_header", "Map", layout.mapHeader) if BaseUI.mapHasData() then BaseUI.createMapper() else BaseUI.mapPlaceholder = Geyser.Label:new({ name = "BaseUI_map_placeholder", x = "0%", y = layout.map.y, width = "100%", height = layout.map.height, font = theme.font, fontSize = 10, fgColor = theme.textDim, format = "c", }, BaseUI.container) BaseUI.mapPlaceholder:setStyleSheet(placeholderCss) BaseUI.mapPlaceholder:echo("Your map will appear<br>here as you explore") end BaseUI.chatHeader = BaseUI.sectionHeader("BaseUI_chat_header", "Chat", layout.chatHeader) BaseUI.chats = {} BaseUI.chatTabLabels = {} BaseUI.unread = { all = 0, tells = 0, channels = 0 } BaseUI.activeChatTab = "all" local tabX = { "0%", "34%", "68%" } for i, tab in ipairs(chatTabs) do local label = Geyser.Label:new({ name = "BaseUI_tab_" .. tab.key, x = tabX[i], y = layout.tabs.y, width = "32%", height = layout.tabs.height, font = theme.font, fontSize = 9, format = "c", }, BaseUI.container) label:setClickCallback(BaseUI.selectChatTab, tab.key) BaseUI.chatTabLabels[tab.key] = label local console = Geyser.MiniConsole:new({ name = "BaseUI_chat_" .. tab.key, x = "0%", y = layout.chat.y, width = "100%", height = layout.chat.height, autoWrap = true, -- plain black so trigger-captured lines (which keep the main console's -- background colour) blend in seamlessly color = "black", fontSize = 10, }, BaseUI.container) BaseUI.chats[tab.key] = console if tab.key ~= "all" then console:hide() end end BaseUI.chat = BaseUI.chats.all BaseUI.refreshChatTabs() BaseUI.chats.all:decho("<150,158,167>Tells, says and channel chat from the game will be collected here.\n") -- the container remembers its own hidden/detached state from the previous -- session (it saves on exit) - our setting says it should be visible, so -- override whatever it restored if not BaseUI.dormant() then BaseUI.container:show() if not BaseUI.container.attached then BaseUI.container:attachToBorder("right") end end BaseUI.maybeAnnounce() end
function BaseUI.refreshChatTabs() for _, tab in ipairs(chatTabs) do local label = BaseUI.chatTabLabels and BaseUI.chatTabLabels[tab.key] if label then local active = BaseUI.activeChatTab == tab.key label:setStyleSheet(active and tabCss.active or tabCss.inactive) local text = tab.label local unread = BaseUI.unread[tab.key] if unread > 0 and not active then text = string.format("%s (%d)", tab.label, math.min(unread, 99)) end label:echo(text, active and theme.text or theme.textDim) end end end
function BaseUI.selectChatTab(key) if not BaseUI.chats or not BaseUI.chats[key] then return end BaseUI.activeChatTab = key BaseUI.unread[key] = 0 for _, tab in ipairs(chatTabs) do local console = BaseUI.chats[tab.key] if tab.key == key then console:show() else console:hide() end end BaseUI.refreshChatTabs() end
function BaseUI.noteChatActivity(key) if key == BaseUI.activeChatTab then return end BaseUI.unread[key] = (BaseUI.unread[key] or 0) + 1 BaseUI.refreshChatTabs() end
-- keep the created gauges in vitalsStats order and packed from the top, -- whatever order their data completed in (a percentage can be ready before -- the hp maxima have arrived) function BaseUI.layoutGauges() local index = 0 for _, stat in ipairs(vitalsStats) do local gauge = BaseUI.gauges[stat.key] if gauge then index = index + 1 gauge:move("0%", layout.gaugeSlots[index]) end end end
function BaseUI.ensureGauge(key) local gauge = BaseUI.gauges[key] if gauge then return gauge end local slot = layout.gaugeSlots[BaseUI.usedGaugeSlots + 1] local def = gaugeDefs[key] if not slot or not def then return nil end BaseUI.usedGaugeSlots = BaseUI.usedGaugeSlots + 1 gauge = Geyser.Gauge:new({ name = "BaseUI_" .. key .. "_gauge", x = "0%", y = slot, width = "100%", height = layout.gaugeHeight, strict = true, font = theme.font, fontSize = 9, }, BaseUI.container) gauge:setStyleSheet(def.front, gaugeBack, gaugeText) gauge:setFgColor("white") gauge:setAlignment("l") gauge:setBold(true) BaseUI.gauges[key] = gauge BaseUI.layoutGauges() return gauge end
local function completeReading(data) if not data then return false end if data.percent then return true end return data.current ~= nil and data.max ~= nil and data.max > 0 end
-- the single entry point every vitals source feeds. snapshot sources (GMCP, -- MSDP) resend everything they know each time, so their stats replace what -- is stored and a transient stat they no longer mention is gone; the prompt -- layer sees one line at a time and merges instead, letting a score screen's -- maxima complete a prompt's bare currents. A source ranked lower than the -- lock's owner is ignored outright. function BaseUI.applyVitals(source, readings, snapshot) local rank = sourceRanks[source] if BaseUI.dormant() or rank < BaseUI.vitalsLock then return end if rank > BaseUI.vitalsLock and completeReading(readings.hp) then -- a better source proved itself with a full hp reading: it takes over -- the lock and everything the previous source reported is dropped BaseUI.vitalsData = {} BaseUI.vitalsLock = rank end for _, stat in ipairs(vitalsStats) do local reading = readings[stat.key] if snapshot then BaseUI.vitalsData[stat.key] = reading elseif reading and not stat.transient then local data = BaseUI.vitalsData[stat.key] or {} data.current = reading.current or data.current data.max = reading.max or data.max data.percent = reading.percent or data.percent BaseUI.vitalsData[stat.key] = data end end BaseUI.renderVitals() end
function BaseUI.renderVitals() if BaseUI.dormant() then return end local paintable = false for _, stat in ipairs(vitalsStats) do if completeReading(BaseUI.vitalsData[stat.key]) then paintable = true break end end if not paintable and not BaseUI.container then return end BaseUI.build() BaseUI.checkMapData() for _, stat in ipairs(vitalsStats) do -- a gauge is only painted once a full reading is known: either a ready -- percentage, or both a current and a max (maxima are never assumed, so -- a stat may wait for a Maxstats message or a score screen) local data = BaseUI.vitalsData[stat.key] or {} if data.percent then local gauge = BaseUI.ensureGauge(stat.key) if gauge then gauge:setValue(data.percent, 100, string.format("%s %d%%", stat.label, math.floor(data.percent + 0.5))) if gauge.hidden then gauge:show() end end elseif data.current and data.max and data.max > 0 then local gauge = BaseUI.ensureGauge(stat.key) if gauge then gauge:setValue(data.current, data.max, string.format("%s %d/%d", stat.label, data.current, data.max)) if gauge.hidden then gauge:show() end end elseif stat.transient and BaseUI.gauges[stat.key] and not BaseUI.gauges[stat.key].hidden then BaseUI.gauges[stat.key]:hide() end end end
function BaseUI.updateVitals() local sources = {} for _, path in ipairs(vitalsNodes) do local node = gmcpNode(path) if node then sources[#sources + 1] = node end end if not sources[1] then return end BaseUI.sawGmcpVitals = true if BaseUI.dormant() then return end BaseUI.build() BaseUI.checkMapData() local readings = {} for _, stat in ipairs(vitalsStats) do local current, max, percent = statReading(sources, stat) if percent and (percent < 0 or percent > 100) then percent = nil end if current or max or percent then readings[stat.key] = { current = current, max = max, percent = percent } end end BaseUI.applyVitals("gmcp", readings, true) end
function BaseUI.updateMsdpVitals() if type(msdp) ~= "table" then return end local readings = {} for _, stat in ipairs(msdpStats) do -- MSDP delivers numbers as strings more often than not local current = tonumber(msdp[stat.current]) local max = tonumber(msdp[stat.max]) if stat.transient then -- an opponent at zero health (or one no longer reported) is gone if current and current > 0 and max and max > 0 then readings[stat.key] = { current = current, max = max } end elseif current or max then readings[stat.key] = { current = current, max = max } end end if not next(readings) then return end BaseUI.sawMsdpVitals = true BaseUI.applyVitals("msdp", readings, true) end
-- ask the game to keep our vitals variables reported; servers simply ignore -- the ones they do not know function BaseUI.requestMsdpVitals() local variables = {} for _, stat in ipairs(msdpStats) do table.insert(variables, stat.current) table.insert(variables, stat.max) end table.insert(variables, "OPPONENT_NAME") table.insert(variables, "LEVEL") sendMSDP("REPORT", unpack(variables)) end
function BaseUI.enableMsdpVitals(_, protocol) if protocol ~= "MSDP" then return end BaseUI.msdpReady = true if not BaseUI.dormant() then BaseUI.requestMsdpVitals() end end
-- a reconnect (possibly to a different game or character) starts the ladder -- fresh: recurrence counters, the source lock and the one-time score request -- are all per-connection state. Painted gauges keep their last values until -- fresh data arrives. function BaseUI.handleDisconnect() BaseUI.vitalsData = {} BaseUI.vitalsLock = 0 BaseUI.shapeSightings = {} BaseUI.scoreRequested = false BaseUI.sawGmcpVitals = false BaseUI.sawMsdpVitals = false BaseUI.msdpReady = false -- the chat trigger layer retires itself once GMCP chat shows up; the next -- connection may be to a game without it, so re-arm the triggers (the -- first GMCP chat message will retire them again, and the recentCaptures -- ring already covers the echo race that comes with that) BaseUI.gmcpChat = false BaseUI.createChatTriggers() end
function BaseUI.addChatMessage() local message = gmcp and gmcp.Comm and gmcp.Comm.Channel and gmcp.Comm.Channel.Text if type(message) ~= "table" or type(message.text) ~= "string" then return end -- the game sends chat over GMCP and usually echoes it as plain text too - -- retire the generic triggers for this session so lines are not captured twice BaseUI.gmcpChat = true BaseUI.killChatTriggers() if BaseUI.dormant() then return end BaseUI.build() -- the first GMCP messages race their own plain-text echoes: an echo can be -- trigger-captured moments before this handler learns the game speaks GMCP -- chat, so drop a message whose text was just captured as a line if next(BaseUI.recentCaptures) then local plain = message.text:gsub("\27%[[0-9;:]*m", "") local now = getEpoch() for i = #BaseUI.recentCaptures, 1, -1 do local capture = BaseUI.recentCaptures[i] if now - capture.time > 2 then table.remove(BaseUI.recentCaptures, i) elseif capture.text == plain then table.remove(BaseUI.recentCaptures, i) return end end end local text = ansi2decho(message.text) .. "\n" BaseUI.chats.all:decho(text) BaseUI.noteChatActivity("all") local channel = type(message.channel) == "string" and message.channel:lower() or "" local family = channel:find("tell", 1, true) and "tells" or "channels" BaseUI.chats[family]:decho(text) BaseUI.noteChatActivity(family) end
-- ask the game to send channel text over GMCP (not all games do so unprompted) function BaseUI.enableChannelCapture(_, protocol) if protocol ~= "GMCP" or BaseUI.dormant() then return end gmod.enableModule("BaseUI", "Comm.Channel") end
function BaseUI.maybeAnnounce() if BaseUI.settings.announced then return end -- respect the first-run UI tour: hold the introduction until it is done if mudlet and mudlet.uiTourPending then registerAnonymousEventHandler("sysUiTourFinished", "BaseUI.announce", true) return end BaseUI.announce() end
function BaseUI.announce() -- dormant covers the tour-finished callback arriving after the UI has -- already stepped aside or been hidden - no point introducing it then if BaseUI.settings.announced or BaseUI.dormant() then return end BaseUI.settings.announced = true BaseUI.saveSettings() cecho("\n<cyan>[ Mudlet UI ] Built you a starter interface from what your game supports - health bars, map and chat.\n") cecho("<cyan>[ Mudlet UI ] Drag its title bar to move it, right-click for options, or type <yellow>baseui hide<cyan> to remove it.<reset>\n") end
function BaseUI.hide() BaseUI.settings.hidden = true BaseUI.saveSettings() BaseUI.killChatTriggers() BaseUI.killVitalsTriggers() if BaseUI.container then BaseUI.container:hide() BaseUI.container:adjustBorder() end cecho("\n<cyan>[ Mudlet UI ] Hidden - type <yellow>baseui show<cyan> to bring it back.<reset>\n") end
function BaseUI.show() BaseUI.settings.hidden = false BaseUI.settings.standingAside = nil BaseUI.saveSettings() if type(gmcp) == "table" and next(gmcp) then gmod.enableModule("BaseUI", "Comm.Channel") end if BaseUI.msdpReady then BaseUI.requestMsdpVitals() end BaseUI.updateVitals() BaseUI.updateMsdpVitals() BaseUI.createChatTriggers() BaseUI.createVitalsTriggers() BaseUI.renderVitals() if BaseUI.container then BaseUI.container:show() if not BaseUI.container.attached then BaseUI.container:attachToBorder("right") end BaseUI.checkMapData() cecho("\n<cyan>[ Mudlet UI ] Shown.<reset>\n") else cecho("\n<cyan>[ Mudlet UI ] It will appear as soon as the game sends chat or character data.<reset>\n") end end
function BaseUI.alias(input) input = (input or ""):trim():lower() if input == "hide" then BaseUI.hide() elseif input == "show" then BaseUI.show() else local state if BaseUI.settings.hidden then state = "hidden" elseif BaseUI.settings.standingAside then state = "standing aside for the game's own interface" elseif BaseUI.container then state = "shown" else state = "waiting for game data" end cecho("\n<cyan>[ Mudlet UI ] A starter interface built from your game's data (currently " .. state .. ").\n") cecho("<cyan>[ Mudlet UI ] <yellow>baseui hide<cyan> - hide it (remembered between sessions)\n") cecho("<cyan>[ Mudlet UI ] <yellow>baseui show<cyan> - bring it back<reset>\n") end end
BaseUI.loadSettings() -- the chat triggers exist from the start (unless the UI is hidden) so the -- interface can appear on the first chat line even on games without GMCP; -- the vitals triggers come second so a chat line is routed (and marked as -- chat) before the vitals layer gets a look at it BaseUI.createChatTriggers() BaseUI.createVitalsTriggers() -- negotiate MSDP up front: it costs nothing on servers without it and gives -- gauges to games that have it but lack GMCP setConfig("enableMSDP", true)
registerAnonymousEventHandler("gmcp.Char.Vitals", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.vitals", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Char.Maxstats", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.maxstats", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Char.Status", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.status", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Comm.Channel.Text", "BaseUI.addChatMessage") registerAnonymousEventHandler("sysProtocolEnabled", "BaseUI.enableChannelCapture") registerAnonymousEventHandler("sysProtocolEnabled", "BaseUI.enableMsdpVitals") registerAnonymousEventHandler("sysDisconnectionEvent", "BaseUI.handleDisconnect") registerAnonymousEventHandler("sysServerGuiInstalled", "BaseUI.standAside") registerAnonymousEventHandler("sysUninstallPackage", "BaseUI.serverGuiRemoved") for _, stat in ipairs(msdpStats) do registerAnonymousEventHandler("msdp." .. stat.current, "BaseUI.updateMsdpVitals") registerAnonymousEventHandler("msdp." .. stat.max, "BaseUI.updateMsdpVitals") end registerAnonymousEventHandler("mapOpenEvent", "BaseUI.checkMapData") registerAnonymousEventHandler("sysMapDownloadEvent", "BaseUI.checkMapData") registerAnonymousEventHandler("sysMapAreaChanged", "BaseUI.checkMapData") registerAnonymousEventHandler("gmcp.Room.Info", "BaseUI.checkMapData") registerAnonymousEventHandler("gmcp.room.info", "BaseUI.checkMapData")
